"use client"

/**
 * @fileoverview Rotating word animation — "Build [websites/apps/products] faster".
 * @author Saasflare™
 * Cycles through an array of words with a vertical flip animation.
 * The container auto-sizes to the longest word to prevent layout shifts.
 * @module packages/ui/components/ui/flip-words
 * @package ui
 *
 * @component
 * @example
 * import { FlipWords } from '@saasflare/ui';
 * <h1>
 *   Build <FlipWords words={["websites", "apps", "products"]} /> faster
 * </h1>
 *
 * @example
 * // Custom interval and color
 * <FlipWords
 *   words={["scalable", "reliable", "beautiful"]}
 *   interval={3000}
 *   className="text-primary"
 * />
 *
 * @example
 * // Freeze the flip via the provider kill-switch or per-instance
 * <FlipWords words={["websites", "apps"]} animated={false} />
 */

import * as React from "react"
import { useState, useEffect, useCallback, useMemo } from "react"
import { AnimatePresence, m } from "motion/react"
import { cn } from "@saasflare/ui"
import {
  useSaasflareProps,
  type SaasflareComponentProps,
} from "@saasflare/ui"
import { springBouncy, useSaasflareMotion } from "@saasflare/ui"

/** Props for the FlipWords component. */
export interface FlipWordsProps
  extends Omit<React.ComponentProps<"span">, keyof SaasflareComponentProps>,
    SaasflareComponentProps {
  /** Array of words to cycle through. */
  words: string[]
  /** Cycle interval in milliseconds. Default: `2500` */
  interval?: number
  /** Additional class names. */
  className?: string
}

/**
 * Inline word rotator with vertical flip animation.
 *
 * - Words flip upward with a spring transition
 * - Container width matches the longest word to prevent layout shifts
 * - Falls back to showing the first word statically when motion is disabled
 *   (reduced-motion preference or `animated={false}` from prop/provider)
 * - Renders inline, so it can be placed mid-sentence
 *
 * @component
 * @package ui
 */
export function FlipWords({
  words,
  interval = 2500,
  className,
  surface,
  radius,
  animated,
  iconWeight,
  ...rest
}: FlipWordsProps) {
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })
  const motion = useSaasflareMotion(sf.animated, springBouncy)
  const [index, setIndex] = useState(0)

  const next = useCallback(() => {
    setIndex((prev) => (prev + 1) % words.length)
  }, [words.length])

  useEffect(() => {
    if (motion.disabled || words.length <= 1) return
    const timer = setInterval(next, interval)
    return () => clearInterval(timer)
  }, [motion.disabled, words.length, interval, next])

  // Invisible spacer with the longest word to prevent layout shifts
  const longestWord = useMemo(
    () => words.reduce((a, b) => (a.length >= b.length ? a : b), ""),
    [words],
  )

  if (motion.disabled) {
    return (
      <span className={className} {...rest}>
        {words[0]}
      </span>
    )
  }

  return (
    <span
      className={cn("relative inline-block text-left align-baseline", className)}
      data-slot="flip-words"
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
      // Live region lives on the STABLE container, not the per-cycle keyed span —
      // a freshly-mounted live region is not reliably announced.
      aria-live="polite"
      aria-atomic="true"
      {...rest}
    >
      {/* Invisible spacer for width */}
      <span className="invisible" aria-hidden="true">{longestWord}</span>

      <AnimatePresence mode="wait">
        <m.span
          key={index}
          initial={{ y: "100%", opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: "-100%", opacity: 0 }}
          transition={motion.transition}
          className="absolute inset-0"
        >
          {words[index]}
        </m.span>
      </AnimatePresence>
    </span>
  )
}
